from __future__ import annotations

import argparse
import json
import math
import sys
from numbers import Integral, Real
from pathlib import Path


TASK_DIR = Path(__file__).resolve().parent
SOURCE = TASK_DIR / "source"
if str(SOURCE) not in sys.path:
    sys.path.insert(0, str(SOURCE))

from desc.stability.terpsichore.benchmark import compare_ladder_reports, run_case  # noqa: E402


def json_safe(value: object) -> object:
    if isinstance(value, bool) or value is None or isinstance(value, str):
        return value
    if isinstance(value, Integral):
        return int(value)
    if isinstance(value, Real):
        numeric = float(value)
        return numeric if math.isfinite(numeric) else None
    if isinstance(value, dict):
        return {str(key): json_safe(item) for key, item in value.items()}
    if isinstance(value, (list, tuple)):
        return [json_safe(item) for item in value]
    return value


def strict_json(value: object) -> str:
    return json.dumps(json_safe(value), indent=2, sort_keys=True, allow_nan=False)


def numeric_observation_state(value: object) -> tuple[int, bool]:
    if isinstance(value, bool):
        return 0, True
    if isinstance(value, Real):
        finite = math.isfinite(float(value))
        return int(finite), finite
    if isinstance(value, dict):
        states = [numeric_observation_state(item) for item in value.values()]
    elif isinstance(value, (list, tuple)):
        states = [numeric_observation_state(item) for item in value]
    else:
        return 0, True
    return sum(count for count, _ in states), all(finite for _, finite in states)


def write_outputs(payload: dict) -> None:
    output_dir = TASK_DIR / "outputs"
    output_dir.mkdir(exist_ok=True)
    report_path = output_dir / "public_boundary_ladder_report.json"
    summary_path = output_dir / "public_boundary_ladder_summary.txt"
    report_path.write_text(strict_json(payload) + "\n", encoding="utf-8")
    lines = [
        f"status: {payload['status']}",
        f"finite_observation_count: {payload['finite_observation_count']}",
    ]
    if payload["status"] == "workflow_completed":
        free = payload["free_boundary"]
        soft = payload["soft_fixed_boundary"]
        hard = payload["hard_fixed_boundary"]
        free_to_soft = payload["contrasts"]["free_to_soft"]
        soft_to_hard = payload["contrasts"]["soft_to_hard"]
        lines.extend(
            [
                f"free_case: {free['case']}",
                f"soft_case: {soft['case']}",
                f"hard_case: {hard['case']}",
                f"soft_response_edge: {soft['boundary_profiles']['response_edge']:.8g}",
                f"hard_response_edge: {hard['boundary_profiles']['response_edge']:.8g}",
                f"soft_closure_edge: {soft['boundary_profiles']['closure_edge']:.8g}",
                f"hard_closure_edge: {hard['boundary_profiles']['closure_edge']:.8g}",
                f"soft_c3_edge_to_core_ratio: {soft['coefficients']['c3_edge_to_core_ratio']:.8g}",
                f"hard_c3_edge_to_core_ratio: {hard['coefficients']['c3_edge_to_core_ratio']:.8g}",
                f"soft_ai_edge_to_core_ratio: {soft['operators']['AI_edge_to_core_ratio']:.8g}",
                f"hard_ai_edge_to_core_ratio: {hard['operators']['AI_edge_to_core_ratio']:.8g}",
                f"soft_edge_energy_fraction: {soft['interval_energy']['edge_fraction']:.8g}",
                f"hard_edge_energy_fraction: {hard['interval_energy']['edge_fraction']:.8g}",
                f"soft_growth_rate_proxy: {soft['energy_scalars']['growth_rate_proxy']:.8g}",
                f"hard_growth_rate_proxy: {hard['energy_scalars']['growth_rate_proxy']:.8g}",
                f"free_to_soft_edge_coefficient_reduction: {free_to_soft['edge_coefficient_reduction']:.8g}",
                f"soft_to_hard_edge_coefficient_reduction: {soft_to_hard['edge_coefficient_reduction']:.8g}",
                f"free_to_soft_edge_operator_reduction: {free_to_soft['edge_operator_reduction']:.8g}",
                f"soft_to_hard_edge_operator_reduction: {soft_to_hard['edge_operator_reduction']:.8g}",
                f"free_to_soft_edge_energy_reduction: {free_to_soft['edge_energy_reduction']:.8g}",
                f"soft_to_hard_edge_energy_reduction: {soft_to_hard['edge_energy_reduction']:.8g}",
            ]
        )
    summary_path.write_text("\n".join(lines) + "\n", encoding="utf-8")


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.parse_args()

    free = run_case(
        TASK_DIR / "fixtures" / "public_free_boundary_reference" / "case.json"
    )
    soft = run_case(
        TASK_DIR / "fixtures" / "public_soft_fixed_boundary_case" / "case.json"
    )
    hard = run_case(
        TASK_DIR / "fixtures" / "public_hard_fixed_boundary_case" / "case.json"
    )
    ladder = compare_ladder_reports(free, soft, hard)
    observations = {
        "free_boundary": free,
        "soft_fixed_boundary": soft,
        "hard_fixed_boundary": hard,
        "contrasts": ladder,
    }
    observation_count, all_finite = numeric_observation_state(observations)
    payload = {
        "status": "workflow_completed"
        if observation_count > 0 and all_finite
        else "incomplete_observation",
        "finite_observation_count": observation_count,
        **observations,
    }
    write_outputs(payload)
    print(strict_json(payload))
    return 0 if payload["status"] == "workflow_completed" else 1


if __name__ == "__main__":
    raise SystemExit(main())
"""Boundary-option helpers for reduced fixed-boundary TERPSICHORE tasks."""

from __future__ import annotations

from dataclasses import dataclass

import numpy as np


@dataclass(frozen=True)
class TerpsichoreBoundaryOptions:
    """Reduced boundary-condition controls for the stability workflow."""

    boundary_condition: str = "free"
    boundary_stiffness: float = 0.0
    boundary_transition_power: float = 2.0
    boundary_operator_closure: float = 0.0

    def __post_init__(self) -> None:
        condition = str(self.boundary_condition).strip().lower()
        if condition not in {"free", "fixed"}:
            raise ValueError("boundary_condition must be 'free' or 'fixed'.")
        if self.boundary_stiffness < 0.0:
            raise ValueError("boundary_stiffness must be non-negative.")
        if self.boundary_transition_power <= 0.0:
            raise ValueError("boundary_transition_power must be positive.")
        if self.boundary_operator_closure < 0.0:
            raise ValueError("boundary_operator_closure must be non-negative.")
        object.__setattr__(self, "boundary_condition", condition)

    @classmethod
    def from_case(cls, case: dict) -> "TerpsichoreBoundaryOptions":
        return cls(
            boundary_condition=case.get("boundary_condition", "free"),
            boundary_stiffness=float(case.get("boundary_stiffness", 0.0)),
            boundary_transition_power=float(case.get("boundary_transition_power", 2.0)),
            boundary_operator_closure=float(case.get("boundary_operator_closure", 0.0)),
        )

    def _edge_coordinate(self, centers: np.ndarray) -> np.ndarray:
        centers = np.asarray(centers, dtype=float)
        if centers.ndim != 1 or centers.size == 0:
            raise ValueError("centers must be a non-empty one-dimensional array.")
        edge = centers / float(np.max(centers))
        return np.clip(edge, 0.0, 1.0)

    def response_profile(self, centers: np.ndarray) -> np.ndarray:
        edge = self._edge_coordinate(centers)
        if self.boundary_condition == "free":
            return np.ones_like(edge)
        return 1.0 / (1.0 + self.boundary_stiffness * edge ** self.boundary_transition_power)

    def closure_profile(self, centers: np.ndarray) -> np.ndarray:
        edge = self._edge_coordinate(centers)
        if self.boundary_condition == "free":
            return np.ones_like(edge)
        taper = 1.0 - 0.35 * self.boundary_operator_closure * edge ** self.boundary_transition_power
        return np.clip(taper, 0.25, None)
"""Reduced FOURIN coefficient generation for boundary-regime capability tasks."""

from __future__ import annotations

from dataclasses import dataclass

import numpy as np


ALL_COEFFICIENTS = ("c0", "c1", "c2", "c3", "c8", "c10", "c11")


@dataclass(frozen=True)
class TerpsichoreCoefficientData:
    """Container for mode-pair-indexed FOURIN-like coefficient arrays."""

    coefficients: dict[str, np.ndarray]
    profiles: dict[str, np.ndarray]
    pair_policy: dict[str, np.ndarray] | None = None

    def __post_init__(self) -> None:
        coeffs = {name: np.asarray(value, dtype=float) for name, value in self.coefficients.items()}
        profiles = {name: np.asarray(value, dtype=float) for name, value in self.profiles.items()}
        pair_policy = (
            {}
            if self.pair_policy is None
            else {name: np.asarray(value) for name, value in self.pair_policy.items()}
        )
        shapes = {value.shape for value in coeffs.values()}
        if len(shapes) != 1:
            raise ValueError("all coefficient arrays must share one shape.")
        for name, value in coeffs.items():
            if value.ndim != 3:
                raise ValueError(f"{name} must be a rank-3 array.")
        if coeffs:
            pair_shape = next(iter(coeffs.values())).shape[:2]
            for name, value in pair_policy.items():
                if value.shape != pair_shape:
                    raise ValueError(f"pair policy {name} must have shape {pair_shape}.")
        object.__setattr__(self, "coefficients", coeffs)
        object.__setattr__(self, "profiles", profiles)
        object.__setattr__(self, "pair_policy", pair_policy)

    def get(self, name: str) -> np.ndarray:
        if name in self.coefficients:
            return self.coefficients[name]
        if name in self.profiles:
            return self.profiles[name]
        raise KeyError(name)

    def as_legacy_dict(self) -> dict[str, np.ndarray]:
        data = dict(self.coefficients)
        data.update(self.profiles)
        data["pair_policy"] = self.pair_policy
        return data


def _fortran_mod(value: int, nper: int) -> int:
    return value - int(value / nper) * nper


def _lsx_lookup(lsx, m_value: int, reduced_n: int, parity: int) -> int:
    if callable(lsx):
        return int(lsx(m_value, reduced_n, parity))
    return int(lsx.get((int(m_value), int(reduced_n), int(parity)), 0))


def compute_fourin_mapping_indices(mode_table, *, nper: int, lsx) -> dict[str, np.ndarray]:
    """Return TERPSICHORE-style sum/difference lookup indices for mode pairs."""

    lmns = mode_table.size
    lmd = np.zeros((lmns, lmns), dtype=int)
    lmp = np.zeros((lmns, lmns), dtype=int)
    ndd = np.zeros((lmns, lmns), dtype=int)
    ndp = np.zeros((lmns, lmns), dtype=int)
    ld = np.zeros((lmns, lmns), dtype=int)
    lp = np.zeros((lmns, lmns), dtype=int)
    for left in range(lmns):
        for right in range(lmns):
            diff_n = int(mode_table.n[left] - mode_table.n[right])
            sum_n = int(mode_table.n[left] + mode_table.n[right])
            lmd[left, right] = min(1, abs(_fortran_mod(diff_n, nper)))
            lmp[left, right] = min(1, abs(_fortran_mod(sum_n, nper)))
            ndd[left, right] = int(diff_n / nper)
            ndp[left, right] = int(sum_n / nper)
            ld[left, right] = _lsx_lookup(
                lsx,
                int(mode_table.m[left] - mode_table.m[right]),
                int(ndd[left, right]),
                int(lmd[left, right]),
            )
            lp[left, right] = _lsx_lookup(
                lsx,
                int(mode_table.m[left] + mode_table.m[right]),
                int(ndp[left, right]),
                int(lmp[left, right]),
            )
    return {"lmd": lmd, "lmp": lmp, "ndd": ndd, "ndp": ndp, "ld": ld, "lp": lp}


def build_fourin_pair_policy(mode_table, indices: dict[str, np.ndarray], *, nper: int) -> dict[str, np.ndarray]:
    """Build the reduced mode-pair support policy shared by FOURIN and assembly."""

    del nper
    has_difference = indices["ld"] > 0
    has_sum = indices["lp"] > 0
    retained_block = mode_table.n[:, None] == mode_table.n[None, :]
    active = retained_block & (has_difference | has_sum)
    coupling_weight = np.where(active, 1.0, 0.0)
    return {
        "has_difference": has_difference,
        "has_sum": has_sum,
        "difference_active": active & has_difference,
        "sum_active": active & has_sum,
        "coefficient_active": active,
        "matrix_active": active,
        "coefficient_weight": coupling_weight,
        "matrix_weight": coupling_weight,
    }


def _validate_integrals(cna: np.ndarray, cnb: np.ndarray) -> tuple[np.ndarray, np.ndarray]:
    cna = np.asarray(cna, dtype=float)
    cnb = np.asarray(cnb, dtype=float)
    if cna.ndim != 3 or cnb.ndim != 3 or cna.shape != cnb.shape:
        raise ValueError("cna and cnb must be rank-3 arrays with matching shape.")
    if cna.shape[0] < 7:
        raise ValueError("cna/cnb must include reduced indices 0..6.")
    return cna, cnb


def _project(integrals: np.ndarray, component: int, lookup: np.ndarray, interval: int, active: np.ndarray) -> np.ndarray:
    gathered = integrals[component, lookup, interval]
    return np.where(active, gathered, 0.0)


def map_fourin_integrals_to_coefficients(
    *,
    cna,
    cnb,
    mode_table,
    trig_table,
    profiles,
    dtdp: float = 1.0,
    cospar: float = 1.0,
    cospr2: float = 1.0,
) -> TerpsichoreCoefficientData:
    """Map raw FOURIN-like integrals into mode-pair coefficient tensors."""

    del cospr2
    cna, cnb = _validate_integrals(cna, cnb)
    intervals = cna.shape[2]
    lmns = mode_table.size
    shape = (lmns, lmns, intervals)
    coeffs = {name: np.zeros(shape) for name in ALL_COEFFICIENTS}
    indices = compute_fourin_mapping_indices(mode_table, nper=trig_table.nper, lsx=trig_table.lsx)
    ld = indices["ld"]
    lp = indices["lp"]
    pair_policy = build_fourin_pair_policy(mode_table, indices, nper=trig_table.nper)
    difference_active = pair_policy["difference_active"]
    sum_active = pair_policy["sum_active"]
    coefficient_weight = pair_policy["coefficient_weight"]

    ftp = np.asarray(profiles["ftp"], dtype=float)
    fpp = np.asarray(profiles["fpp"], dtype=float)
    boundary_response = np.asarray(profiles.get("boundary_response", np.ones(intervals)), dtype=float)
    boundary_closure = np.asarray(profiles.get("boundary_closure", np.ones(intervals)), dtype=float)
    if ftp.shape != (intervals,) or fpp.shape != (intervals,):
        raise ValueError("profile arrays must have one entry per radial interval.")
    if boundary_response.shape != (intervals,) or boundary_closure.shape != (intervals,):
        raise ValueError("boundary profile arrays must have one entry per radial interval.")

    boundary_scale = float(np.mean(boundary_response))

    for interval in range(intervals):
        c0 = dtdp * (
            _project(cna, 6, ld, interval, difference_active)
            - cospar * _project(cna, 6, lp, interval, sum_active)
        )
        c1 = dtdp * (
            _project(cnb, 1, ld, interval, difference_active)
            + cospar * _project(cnb, 1, lp, interval, sum_active)
        )
        c2 = dtdp * (
            _project(cna, 1, ld, interval, difference_active)
            - cospar * _project(cna, 1, lp, interval, sum_active)
        )
        c3 = dtdp * (
            _project(cnb, 2, ld, interval, difference_active)
            + cospar * _project(cnb, 2, lp, interval, sum_active)
        )
        c8 = dtdp * (
            _project(cnb, 5, ld, interval, difference_active)
            - cospar * _project(cnb, 5, lp, interval, sum_active)
        )
        c10 = dtdp * (
            _project(cnb, 4, ld, interval, difference_active)
            + cospar * _project(cnb, 4, lp, interval, sum_active)
        )
        c11 = dtdp * (
            _project(cnb, 6, ld, interval, difference_active)
            + cospar * _project(cnb, 6, lp, interval, sum_active)
        )
        c0 = coefficient_weight * (0.90 + 0.10 * boundary_scale) * c0
        c1 = coefficient_weight * ftp[interval] * boundary_scale * c1
        c2 = coefficient_weight * fpp[interval] * (0.85 + 0.15 * boundary_scale) * c2
        c3 = coefficient_weight * ftp[interval] * boundary_scale * c3
        c8 = coefficient_weight * (0.92 + 0.08 * boundary_scale) * c8
        c10 = coefficient_weight * fpp[interval] * boundary_scale * c10
        c11 = coefficient_weight * ftp[interval] * boundary_scale * c11

        coeffs["c0"][:, :, interval] = c0
        coeffs["c1"][:, :, interval] = c1
        coeffs["c2"][:, :, interval] = c2
        coeffs["c3"][:, :, interval] = c3
        coeffs["c8"][:, :, interval] = c8
        coeffs["c10"][:, :, interval] = c10
        coeffs["c11"][:, :, interval] = c11

    return TerpsichoreCoefficientData(
        coefficients=coeffs,
        profiles={
            "ftp": ftp,
            "fpp": fpp,
            "boundary_response": boundary_response,
            "boundary_closure": boundary_closure,
        },
        pair_policy=pair_policy,
    )

"""Observation helpers for reduced fixed-boundary TERPSICHORE tasks."""

from __future__ import annotations

import numpy as np

from .assembly import block_interval_norms


def coefficient_interval_norms(coeffs, name: str) -> np.ndarray:
    arr = np.asarray(coeffs.get(name), dtype=float)
    if arr.ndim != 3:
        raise ValueError(f"{name} must be a rank-3 coefficient array.")
    return np.asarray([np.linalg.norm(arr[:, :, idx]) for idx in range(arr.shape[2])], dtype=float)


def edge_to_core_ratio(values: np.ndarray) -> float:
    values = np.asarray(values, dtype=float)
    if values.ndim != 1 or values.size < 2:
        raise ValueError("values must be a one-dimensional array with at least two entries.")
    core = float(np.mean(values[:-1]))
    edge = float(values[-1])
    return float(edge / max(core, 1e-30))


def build_report(case: dict, coeffs, potential, kinetic, energy: dict[str, object]) -> dict:
    c3_norms = coefficient_interval_norms(coeffs, "c3")
    c10_norms = coefficient_interval_norms(coeffs, "c10")
    ai_norms = block_interval_norms(potential.AI)
    bd_norms = block_interval_norms(kinetic.BD)
    report = {
        "case": case["name"],
        "boundary_condition": case.get("boundary_condition", "free"),
        "mode_count": int(coeffs.get("c3").shape[0]),
        "boundary_profiles": {
            "response_profile": [float(x) for x in np.asarray(coeffs.get("boundary_response"), dtype=float)],
            "closure_profile": [float(x) for x in np.asarray(coeffs.get("boundary_closure"), dtype=float)],
            "response_edge": float(np.asarray(coeffs.get("boundary_response"), dtype=float)[-1]),
            "closure_edge": float(np.asarray(coeffs.get("boundary_closure"), dtype=float)[-1]),
        },
        "coefficients": {
            "c3_interval_norms": [float(x) for x in c3_norms],
            "c10_interval_norms": [float(x) for x in c10_norms],
            "c3_edge_to_core_ratio": edge_to_core_ratio(c3_norms),
            "c10_edge_to_core_ratio": edge_to_core_ratio(c10_norms),
        },
        "operators": {
            "AI_interval_norms": [float(x) for x in ai_norms],
            "BD_interval_norms": [float(x) for x in bd_norms],
            "AI_edge_to_core_ratio": edge_to_core_ratio(ai_norms),
            "BD_edge_to_core_ratio": edge_to_core_ratio(bd_norms),
        },
        "interval_energy": {
            "interval_potential": energy["interval_potential"],
            "interval_kinetic": energy["interval_kinetic"],
            "interval_total": energy["interval_total"],
            "edge_fraction": float(energy["edge_fraction"]),
            "core_fraction": float(energy["core_fraction"]),
            "potential_kinetic_mismatch": float(energy["potential_kinetic_mismatch"]),
        },
        "energy_scalars": {
            "total_energy": float(energy["total_energy"]),
            "closure_score": float(energy["closure_score"]),
            "growth_rate_proxy": float(energy["growth_rate_proxy"]),
        },
    }
    return report


def compare_case_reports(baseline: dict, fixed_boundary: dict) -> dict:
    coeff_reduction = 1.0 - (
        fixed_boundary["coefficients"]["c3_edge_to_core_ratio"]
        / max(baseline["coefficients"]["c3_edge_to_core_ratio"], 1e-30)
    )
    operator_reduction = 1.0 - (
        fixed_boundary["operators"]["AI_edge_to_core_ratio"]
        / max(baseline["operators"]["AI_edge_to_core_ratio"], 1e-30)
    )
    edge_energy_reduction = 1.0 - (
        fixed_boundary["interval_energy"]["edge_fraction"]
        / max(baseline["interval_energy"]["edge_fraction"], 1e-30)
    )
    growth_rate_reduction = 1.0 - (
        fixed_boundary["energy_scalars"]["growth_rate_proxy"]
        / max(baseline["energy_scalars"]["growth_rate_proxy"], 1e-30)
    )
    return {
        "edge_coefficient_reduction": float(coeff_reduction),
        "edge_operator_reduction": float(operator_reduction),
        "edge_energy_reduction": float(edge_energy_reduction),
        "growth_rate_reduction": float(growth_rate_reduction),
    }


def compare_ladder_reports(free: dict, soft: dict, hard: dict) -> dict:
    free_to_soft = compare_case_reports(free, soft)
    soft_to_hard = compare_case_reports(soft, hard)
    return {
        "free_to_soft": free_to_soft,
        "soft_to_hard": soft_to_hard,
    }
